"""Ascon: the Ascon permutation."""

from primitives.primitives import Permutation
from operators.Sbox import ASCON_Sbox
from operators.boolean_operators import XOR, N_XOR
import variables.variables as var


# The ASCON internal permutation      
class ASCON_permutation(Permutation):
    def __init__(self, name, s_input, s_output, nbr_rounds=None, represent_mode=0):
        """
        Initialize the ASCON internal permutation

        Args:
            name: Name of the permutation
            version: Bit size of the permutation
            s_input: Input state
            s_output: Output state
            nbr_rounds: Number of rounds
            represent_mode: Integer specifying the mode of representation used for encoding the permutation.
        """
        if nbr_rounds is None: nbr_rounds=12
        if represent_mode==0: nbr_layers, nbr_words, nbr_temp_words, word_bitsize = (4, 320, 320, 1)
        elif represent_mode==1: nbr_layers, nbr_words, nbr_temp_words, word_bitsize = (3, 320, 0, 1)
        super().__init__(name, s_input, s_output, nbr_rounds, [nbr_layers, nbr_words, nbr_temp_words, word_bitsize])
        
        S = self.functions["PERMUTATION"]
        constant_table = self.gen_rounds_constant_table()

        # Ascon Sigma linear layer: per 64-bit lane, XOR each bit with two shifted copies of the lane;
        SIGMA = [(45, 36), (3, 25), (63, 58), (54, 47), (57, 23)]
        if represent_mode==0:
            xor_index_in = [[(a+j)%64 + 64*L, (b+j)%64 + 64*L]
                            for L, (a, b) in enumerate(SIGMA) for j in range(64)]
            for i in range(1,nbr_rounds+1):
                S.AddConstantLayer("C", i, 0, "xor", [None]*184+[True]*8, constant_table)  # Constant layer      
                S.SboxLayer("SB", i, 1, ASCON_Sbox, index=[[k+j*64 for j in range(5)] for k in range(64)])  # Sbox layer            
                S.SingleOperatorLayer("XOR", i, 2, XOR, xor_index_in, [j for j in range(320,640)]) # XOR layer 
                S.SingleOperatorLayer("XOR", i, 3, XOR, [[j, j+320] for j in range(320)], [j for j in range(320)]) # XOR layer 

        elif represent_mode==1:
            xor_index_in = [[64*L + j, (a+j)%64 + 64*L, (b+j)%64 + 64*L]
                            for L, (a, b) in enumerate(SIGMA) for j in range(64)]
            for i in range(1,nbr_rounds+1):
                S.AddConstantLayer("C", i, 0, "xor", [None]*184+[True]*8, constant_table)  # Constant layer      
                S.SboxLayer("SB", i, 1, ASCON_Sbox, index=[[k+j*64 for j in range(5)] for k in range(64)])  # Sbox layer            
                S.SingleOperatorLayer("3_XOR", i, 2, N_XOR, xor_index_in, [j for j in range(320)]) # 3-XOR layer 

    def gen_rounds_constant_table(self):
        constant_table = []
        cons = [0xf0 - r*0x10 + r*0x1 for r in range(12)]
        for i in range(1,self.functions["PERMUTATION"].nbr_rounds+1):  
            constant_table.append([((cons[12-self.functions["PERMUTATION"].nbr_rounds+i-1] >> (7-l)) & 1) for l in range(8)])
        return constant_table
    
